```python
import requests

class EducationalResources:
    def __init__(self, api_key):
        self.api_key = api_key
        self.base_url = 'https://api.example.com/educational-resources'

    def search(self, keyword):
        """
        Search for educational resources using a keyword
        """
        url = f'{self.base_url}/search'
        params = {'api_key': self.api_key, 'q': keyword}
        response = requests.get(url, params=params)

        if response.status_code == 200:
            results = response.json()
            return results
        else:
            return None

    def get_categories(self):
        """
        Get a list of available categories for educational resources
        """
        url = f'{self.base_url}/categories'
        params = {'api_key': self.api_key}
        response = requests.get(url, params=params)

        if response.status_code == 200:
            categories = response.json()
            return categories
        else:
            return None

    def get_resources_by_category(self, category):
        """
        Get a list of educational resources by category
        """
        url = f'{self.base_url}/category/{category}'
        params = {'api_key': self.api_key}
        response = requests.get(url, params=params)

        if response.status_code == 200:
            resources = response.json()
            return resources
        else:
            return None

    def get_resource(self, resource_id):
        """
        Get details for a specific educational resource
        """
        url = f'{self.base_url}/{resource_id}'
        params = {'api_key': self.api_key}
        response = requests.get(url, params=params)

        if response.status_code == 200:
            resource = response.json()
            return resource
        else:
            return None
```

This code creates a `EducationalResources` class with methods to search for educational resources by keyword, get a list of available categories, get a list of educational resources by category, and get details for a specific educational resource. The class uses the requests library to make HTTP requests to an external API that provides educational resource data. The API requires an API key, which is passed to the `EducationalResources` class constructor. The class methods handle HTTP response codes and return the data as Python dictionaries. This code could be extended to include additional features such as saving educational resources to a user’s account or allowing users to rate and review resources.

